def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    encrypted = ''

    for char in s:
        if char.isalpha():
            index = alphabet.index(char)
            encrypted += alphabet[(index + 2) % 26]
        else:
            encrypted += char

    return encrypted

